14	pub(crate) fn encode_non_null_values<'a, I: Iterator<Item = &'a [u8]>>(
15	    iter: I,
16	    buffer: &mut Vec<u8>,
17	) {
18	    iter.for_each(|x| {
19	        // BYTE_ARRAY: first 4 bytes denote length in littleendian.
20	        let len = (x.len() as u32).to_le_bytes();
21	        buffer.extend_from_slice(&len);
22	        buffer.extend_from_slice(x);
23	    })
24	}
