26	pub(crate) fn encode_plain<O: Offset>(
27	    array: &BinaryArray<O>,
28	    options: EncodeNullability,
29	    buffer: &mut Vec<u8>,
30	) {
31	    if options.is_optional() && array.validity().is_some() {
32	        let len_before = buffer.len();
33	        let capacity =
34	            array.get_values_size() + (array.len() - array.null_count()) * size_of::<u32>();
35	        buffer.reserve(capacity);
36	        encode_non_null_values(array.non_null_values_iter(), buffer);
37	        // Assert <= as reserve size may include masked out values.
38	        debug_assert!(buffer.len() - len_before <= capacity);
39	    } else {
40	        let len_before = buffer.len();
41	        let capacity = array.get_values_size() + array.len() * size_of::<u32>();
42	        buffer.reserve(capacity);
43	        encode_non_null_values(array.values_iter(), buffer);
44	        // Ensure we allocated properly.
45	        debug_assert_eq!(buffer.len() - len_before, capacity);
46	    }
47	}
