49	pub fn array_to_page<O: Offset>(
50	    array: &BinaryArray<O>,
51	    options: WriteOptions,
52	    type_: PrimitiveType,
53	    encoding: Encoding,
54	) -> PolarsResult<Page> {
55	    let validity = array.validity();
56	    let is_optional = is_nullable(&type_.field_info);
57	    let encode_options = EncodeNullability::new(is_optional);
58	
59	    let mut buffer = vec![];
60	    utils::write_def_levels(
61	        &mut buffer,
62	        is_optional,
63	        validity,
64	        array.len(),
65	        options.version,
66	    )?;
67	
68	    let definition_levels_byte_length = buffer.len();
69	
70	    match encoding {
71	        Encoding::Plain => encode_plain(array, encode_options, &mut buffer),
72	        Encoding::DeltaLengthByteArray => encode_delta(
73	            array.values(),
74	            array.offsets().buffer(),
75	            array.validity(),
76	            encode_options,
77	            &mut buffer,
78	        ),
79	        _ => return Err(invalid_encoding(encoding, array.dtype())),
80	    }
81	
82	    let statistics = if options.has_statistics() {
83	        Some(build_statistics(array, type_.clone(), &options.statistics))
84	    } else {
85	        None
86	    };
87	
88	    utils::build_plain_page(
89	        buffer,
90	        array.len(),
91	        array.len(),
92	        array.null_count(),
93	        0,
94	        definition_levels_byte_length,
95	        statistics,
96	        type_,
97	        options,
98	        encoding,
99	    )
100	    .map(Page::Data)
101	}
