103	pub(crate) fn build_statistics<O: Offset>(
104	    array: &BinaryArray<O>,
105	    primitive_type: PrimitiveType,
106	    options: &StatisticsOptions,
107	) -> ParquetStatistics {
108	    use polars_compute::min_max::MinMaxKernel;
109	
110	    BinaryStatistics {
111	        primitive_type,
112	        null_count: options.null_count.then_some(array.null_count() as i64),
113	        distinct_count: None,
114	        max_value: options
115	            .max_value
116	            .then(|| array.max_propagate_nan_kernel().map(<[u8]>::to_vec))
117	            .flatten(),
118	        min_value: options
119	            .min_value
120	            .then(|| array.min_propagate_nan_kernel().map(<[u8]>::to_vec))
121	            .flatten(),
122	    }
123	    .serialize()
124	}
