126	pub(crate) fn encode_delta<O: Offset>(
127	    values: &[u8],
128	    offsets: &[O],
129	    validity: Option<&Bitmap>,
130	    options: EncodeNullability,
131	    buffer: &mut Vec<u8>,
132	) {
133	    if options.is_optional() && validity.is_some() {
134	        if let Some(validity) = validity {
135	            let lengths = offsets
136	                .windows(2)
137	                .map(|w| (w[1] - w[0]).to_usize() as i64)
138	                .zip(validity.iter())
139	                .flat_map(|(x, is_valid)| if is_valid { Some(x) } else { None });
140	            let length = offsets.len() - 1 - validity.unset_bits();
141	            let lengths = utils::ExactSizedIter::new(lengths, length);
142	
143	            delta_bitpacked::encode(lengths, buffer, 1);
144	        } else {
145	            let lengths = offsets.windows(2).map(|w| (w[1] - w[0]).to_usize() as i64);
146	            delta_bitpacked::encode(lengths, buffer, 1);
147	        }
148	    } else {
149	        let lengths = offsets.windows(2).map(|w| (w[1] - w[0]).to_usize() as i64);
150	        delta_bitpacked::encode(lengths, buffer, 1);
151	    }
152	
153	    buffer.extend_from_slice(
154	        &values[offsets.first().unwrap().to_usize()..offsets.last().unwrap().to_usize()],
155	    )
156	}
