//!
//! Writing the exact minimum and maximum values into the column statistics can bloat the file
//! enormously when the column contains very large values (e.g. a multi-megabyte string). Parquet
//! allows the statistics bounds to be *truncated* as long as the truncated minimum is `<=` the
//! real minimum and the truncated maximum is `>=` the real maximum, so that predicate pushdown
//! stays correct.
//!
//! The truncation length is configurable through the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable. When it is not set, the
//! default is [`DEFAULT_TRUNCATE_LEN`] bytes. When it is set to `0`, truncation is disabled and
//! the exact bounds are written.

use crate::parquet::schema::types::PrimitiveType;

/// Default number of bytes to truncate binary/string statistics to.
pub(crate) const DEFAULT_TRUNCATE_LEN: usize = 64;

const TRUNCATE_LEN_ENV: &str = "POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN";

/// Returns the configured truncation length.
///
/// * `None` means truncation is disabled (env var set to `0`).
/// * `Some(n)` means truncate to at most `n` bytes.
fn truncate_len() -> Option<usize> {
    match std::env::var(TRUNCATE_LEN_ENV) {
        Ok(v) => match v.trim().parse::<usize>() {
            Ok(0) => None,
            Ok(n) => Some(n),
            // Fall back to the default on an unparseable value.
            Err(_) => Some(DEFAULT_TRUNCATE_LEN),
        },
        Err(_) => Some(DEFAULT_TRUNCATE_LEN),
    }
}

/// Whether the given primitive type represents a UTF-8 string column.
fn is_utf8(primitive_type: &PrimitiveType) -> bool {
    use crate::parquet::schema::types::{PrimitiveConvertedType, PrimitiveLogicalType};

    matches!(primitive_type.logical_type, Some(PrimitiveLogicalType::String))
        || matches!(
            primitive_type.converted_type,
            Some(PrimitiveConvertedType::Utf8)
        )
}

/// Truncate the min/max statistics of a `BYTE_ARRAY` column in place, respecting the configured
/// truncation length and whether the column is UTF-8 encoded.
pub(crate) fn truncate_binary_statistics(
    primitive_type: &PrimitiveType,
    min_value: &mut Option<Vec<u8>>,
    max_value: &mut Option<Vec<u8>>,
) {
    let Some(limit) = truncate_len() else {
        // Truncation disabled.
        return;
    };

    let utf8 = is_utf8(primitive_type);

    if let Some(min) = min_value.as_mut() {
        if min.len() > limit {
            *min = truncate_min(min, limit, utf8);
        }
    }
    if let Some(max) = max_value.as_mut() {
        if max.len() > limit {
            if let Some(truncated) = truncate_max(max, limit, utf8) {
                *max = truncated;
            }
        }
    }
}

/// Produce a lower bound: the longest prefix of `value` that fits within `limit` bytes.
///
/// For UTF-8 columns the prefix is cut on a character boundary so it remains valid UTF-8.
fn truncate_min(value: &[u8], limit: usize, utf8: bool) -> Vec<u8> {
    let end = if utf8 {
        utf8_truncate_boundary(value, limit)
    } else {
        limit
    };
    value[..end].to_vec()
}

/// Produce an upper bound: a value `>=` the original that fits within (roughly) `limit` bytes.
///
/// Returns `None` when no valid upper bound could be produced within the constraints, in which
/// case the caller should keep the original value.
fn truncate_max(value: &[u8], limit: usize, utf8: bool) -> Option<Vec<u8>> {
    if utf8 {
        let end = utf8_truncate_boundary(value, limit);
        // SAFETY: `end` is a character boundary of a valid UTF-8 slice.
        let prefix = unsafe { std::str::from_utf8_unchecked(&value[..end]) };
        increment_utf8(prefix)
    } else {
        increment_binary(value, limit)
    }
}

/// Length of the longest UTF-8 prefix of `value` that fits within `limit` bytes, cut on a
/// character boundary so it does not split a multi-byte code point.
fn utf8_truncate_boundary(value: &[u8], limit: usize) -> usize {
    if value.len() <= limit {
        return value.len();
    }
    let mut end = limit;
    // Walk back to the start of the character containing byte `end`. UTF-8 continuation bytes
    // match `0b10xxxxxx`.
    while end > 0 && (value[end] & 0b1100_0000) == 0b1000_0000 {
        end -= 1;
    }
    end
}

/// Produce an upper bound for a binary value truncated to at most `limit` bytes.
///
/// The prefix (`value[..limit]`) is incremented by finding its last non-`0xFF` byte, incrementing
/// it and dropping everything after it. If every byte within the limit is `0xFF`, the search
/// continues beyond the limit to find the first non-`0xFF` byte, which is incremented and used as
/// the upper bound.
fn increment_binary(value: &[u8], limit: usize) -> Option<Vec<u8>> {
    let prefix_len = limit.min(value.len());

    // Try to increment within the truncated prefix.
    for i in (0..prefix_len).rev() {
        if value[i] != 0xFF {
            let mut out = value[..=i].to_vec();
            out[i] += 1;
            return Some(out);
        }
    }

    // The whole prefix is 0xFF: search beyond the limit for the first non-0xFF byte.
    for i in prefix_len..value.len() {
        if value[i] != 0xFF {
            let mut out = value[..=i].to_vec();
            out[i] += 1;
            return Some(out);
        }
    }

    // Every byte is 0xFF: no valid upper bound exists.
    None
}

/// Increment a valid-UTF-8 prefix to produce a valid-UTF-8 upper bound.
///
/// The last character is incremented to the next code point that has the same UTF-8 byte length.
/// If the last character cannot be incremented within its byte length, it is dropped and the
/// previous character is tried instead. Returns `None` if no character could be incremented.
fn increment_utf8(prefix: &str) -> Option<Vec<u8>> {
    for (start, ch) in prefix.char_indices().rev() {
        if let Some(next) = increment_char_same_len(ch) {
            let mut out = prefix.as_bytes()[..start].to_vec();
            let mut buf = [0u8; 4];
            out.extend_from_slice(next.encode_utf8(&mut buf).as_bytes());
            return Some(out);
        }
        // This character is at the maximum of its byte-length range; drop it and try the previous.
    }
    None
}

/// Return the smallest `char` greater than `ch` that encodes to the same number of UTF-8 bytes,
/// or `None` if `ch` is already the largest such character.
fn increment_char_same_len(ch: char) -> Option<char> {
    let len = ch.len_utf8();
    let mut cp = ch as u32;
    loop {
        cp += 1;
        if cp > char::MAX as u32 {
            return None;
        }
        if let Some(next) = char::from_u32(cp) {
            if next.len_utf8() != len {
                return None;
            }
            return Some(next);
        }
        // `cp` fell inside the surrogate range; keep searching for the next scalar value.
    }
}
