    fn utf8_min_char_boundary() {
        // 63 'A' followed by a 2-byte character (U+00E9 = 0xC3 0xA9).
        let mut v = vec![b'A'; 63];
        v.extend_from_slice("é".as_bytes());
        assert_eq!(truncate_min(&v, 64, true), vec![b'A'; 63]);
    }

    #[test]
    fn utf8_max_ascii() {
        let v = vec![b'A'; 100];
        let mut expected = vec![b'A'; 63];
        expected.push(b'B');
        assert_eq!(truncate_max(&v, 64, true).unwrap(), expected);
    }

    #[test]
    fn utf8_max_two_byte_boundary() {
        // 100 copies of U+00E9; truncates to 32 (64 bytes), increments to 31 + U+00EA.
        let v = "é".repeat(100).into_bytes();
        let mut expected = "é".repeat(31).into_bytes();
        expected.extend_from_slice("ê".as_bytes()); // U+00EA
        assert_eq!(truncate_max(&v, 64, true).unwrap(), expected);
    }

